from safety_client import SafetyClient
from safety_models import TextModerationRequest

def redact_unsafe(text: str, threshold: int = 4) -> str:
    client = SafetyClient()
    request = TextModerationRequest(text=text)
    response = client.moderate_text(request)

    is_unsafe = False
    if response.categories:
        for category_result in response.categories:
            if category_result.get("severity", 0) >= threshold:
                is_unsafe = True
                break

    if is_unsafe:
        return "[REDACTED]"
    else:
        return text

from typing import Dict
from safety_models import TextModerationResponse

def apply_safety_thresholds(response: TextModerationResponse, thresholds: Dict[str, int]) -> bool:
    if not response.categories:
        return True  # No issues found, allow by default

    for category_result in response.categories:
        category_name = category_result.get("category")
        severity = category_result.get("severity", 0)

        if category_name and category_name in thresholds:
            if severity >= thresholds[category_name]:
                return False  # Block if severity meets or exceeds the threshold
    return True  # Allow if no thresholds are met or exceeded

import os
from openai import OpenAI
from safety_models import TextModerationResponse

def summarize_moderation_decisions(response: TextModerationResponse) -> str:
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))
    if not client.api_key:
        raise ValueError("OPENAI_API_KEY environment variable must be set.")

    decision_text = "Moderation decisions:\n"
    if response.categories:
        for cat in response.categories:
            decision_text += f"  - Category: {cat.get('category')}, Severity: {cat.get('severity')}\n"
    if response.block_lists_match_result:
        for block_match in response.block_lists_match_result:
            decision_text += f"  - Blocked by list: {block_match.get('block_list_name')}, Item: {block_match.get('block_item_text')}\n"
    if response.sentiment is not None:
        decision_text += f"  - Sentiment: {response.sentiment}\n"

    if not response.categories and not response.block_lists_match_result and response.sentiment is None:
        decision_text += "  No specific issues detected.\n"

    prompt = f"Summarize the following text content moderation decisions:\n{decision_text}"

    try:
        completion = client.chat.completions.create(
            model="gpt-3.5-turbo",
            messages=[
                {"role": "system", "content": "You are a helpful assistant that summarizes content moderation decisions."},
                {"role": "user", "content": prompt}
            ]
        )
        return completion.choices[0].message.content
    except Exception as e:
        return f"Error summarizing moderation decisions: {e}"

import os
from google.cloud import translate_v3 as translate

def translate_appeal_text(text: str, target_language: str = "en") -> str:
    client = translate.TranslationServiceClient()
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")

    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID environment variable must be set.")

    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "target_language_code": target_language,
        }
    )

    translated_text = ""
    for translation in response.translations:
        translated_text += translation.translated_text

    return translated_text

import os
from typing import List
from openai import OpenAI

def embed_moderation_rationale(rationale: str) -> List[float]:
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))
    if not client.api_key:
        raise ValueError("OPENAI_API_KEY environment variable must be set.")

    try:
        response = client.embeddings.create(
            input=rationale,
            model="text-embedding-ada-002"
        )
        return response.data[0].embedding
    except Exception as e:
        raise RuntimeError(f"Error generating embedding: {e}")
